/* R-076: the tactical clock. Baseline is the base tick at setup time, read
 * through the public om_tactical_base_tick(w) getter (csrc/unit.c) so
 * om_mission_is_ended compares against the same clock the tactical engine
 * advances: base ticks, which stay real time when the step period is 2. */
void om_mission_setup_tactical(om_world *w, uint32_t p1, uint64_t time_limit) {
    om_mission_state *st = om_mis(w);
    (void)p1;
    st->tactical_time_limit = time_limit;
    st->tactical_baseline_tick = om_tactical_base_tick(w);
    st->tactical_baseline_pending = om_mission_get_phase(w) == 0 /* OM_FOG_PHASE_RECON, csrc/fog.c */;
    st->tactical_ended = 0;
}

void om_mission_setup_termination(om_world *w, uint32_t p1, int primary_complete, int p3, uint64_t tick, uint64_t time_limit, int player_alive) {
    om_mission_state *st = om_mis(w);
    (void)p1;
    st->term_primary_complete = primary_complete;
    st->term_primary_failed = p3;
    st->term_tick = tick;
    st->term_time_limit = time_limit;
    st->term_player_alive = player_alive;
}

/* R-118-01 / R-130-02: a centre pushed by om_objective_set_center wins (a
 * drifting objective moves the zone); otherwise the zone is centred on its
 * spine node, read live so a drifting node carries the zone with it.
 * om_map_* take a non-const world but these two are pure getters (same cast
 * precedent as om_mission_is_ended). See also: csrc/tactical_support.c --
 * owns the drifting objective centre and is the caller expected to push it
 * through om_objective_set_center. */
int om_objective_get_center(const om_world *w, uint32_t objective_idx, om_vec2 *out) {
    if (!out) return 0;
    out->x = 0.0;
    out->y = 0.0;
    if (!w) return 0;
    const om_mission_state *st = om_mis_ro(w);
    if (st && objective_idx < OM_MISSION_MAX_OBJECTIVES && st->objective_center_set[objective_idx]) {
        *out = st->objective_center[objective_idx];
        return 1;
    }
    om_world *mw = (om_world *)w;
    if (om_map_count_nodes_of_type(mw, OM_MISSION_SPINE_NODE_OBJECTIVE) <= objective_idx) return 0;
    uint32_t node = om_map_get_nth_node_of_type(mw, OM_MISSION_SPINE_NODE_OBJECTIVE, objective_idx);
    om_map_get_node_pos(mw, node, out);
    return 1;
}

/* Map-node index of objective_idx's spine node, or -1 if absent (same
 * lookup as om_objective_get_center). */
int32_t om_objective_get_node(const om_world *w, uint32_t objective_idx) {
    if (!w) return -1;
    om_world *mw = (om_world *)w;
    if (om_map_count_nodes_of_type(mw, OM_MISSION_SPINE_NODE_OBJECTIVE) <= objective_idx) return -1;
    return (int32_t)om_map_get_nth_node_of_type(mw, OM_MISSION_SPINE_NODE_OBJECTIVE, objective_idx);
}

/* Radius of the cover disc om_mission_instantiate_map places on the objective
 * node; the hold check (om_mission_tactical_tick) counts enemies within this
 * same radius. */
double om_objective_get_radius(const om_world *w, uint32_t objective_idx) {
    if (objective_idx != 0 || om_objective_get_node(w, 0) < 0) return 0.0;
    return OM_MISSION_OBJECTIVE_COVER_RADIUS;
}

/* Q-077-02: 0 ok, 1 unknown or not the player's unit, 2 assigned commander dead. */
int om_mission_assign_commander(om_world *w, uint32_t unit_id) {
    om_mission_state *st = om_mis(w);
    if (!unit_id || unit_id > om_unit_count(w)) return 1;
    int32_t pf = om_mission_player_faction(w);
    int32_t f = om_unit_get_faction(w, unit_id);
    if (f < 0 || (pf >= 0 && f != pf)) return 1;
    if (st->commander_unit && st->commander_unit != unit_id &&
        om_unit_get_hp(w, st->commander_unit) <= 0.0) return 2;
    st->commander_unit = unit_id;
    return 0;
}

uint32_t om_mission_get_commander_unit(const om_world *w) {
    const om_mission_state *st = om_mis_ro(w);
    return st ? st->commander_unit : 0;
}

/* Player-faction units om_mission_spawn_force recorded for this mission. */
uint32_t om_mission_get_force_count(const om_world *w) {
    const om_mission_state *st = om_mis_ro(w);
    if (!st) return 0;
    int32_t player = om_mission_player_faction(w);
    if (player < 0) player = 0;
    uint32_t n = 0;
    for (uint32_t i = 0; i < st->n_force_units; i++)
        if (st->force_units[i].faction == player) n++;
    return n;
}

/* i-th player entry. No per-unit tier source exists, so tier is always 0. */
int om_mission_get_force_unit(const om_world *w, uint32_t i, int32_t *type, int32_t *tier) {
    const om_mission_state *st = om_mis_ro(w);
    if (!st) return 0;
    int32_t player = om_mission_player_faction(w);
    if (player < 0) player = 0;
    uint32_t seen = 0;
    for (uint32_t j = 0; j < st->n_force_units; j++) {
        if (st->force_units[j].faction != player) continue;
        if (seen++ != i) continue;
        if (type) *type = st->force_units[j].type;
        if (tier) *tier = 0;
        return 1;
    }
    return 0;
}

/* B9-3: plain wrappers over E-05's om_region_held_since / om_region_owner
 * (csrc/faction.c) -- the E-10 test suite's own accessor names, same data. */
int64_t om_region_get_held_since(const om_world *w, uint32_t idx) {
    return om_region_held_since(w, idx);
}

int32_t om_region_get_owner(const om_world *w, uint32_t idx) {
    return om_region_owner(w, idx);
}

/* B9-3 (R-078-07 fixture helper): one-directional adjacency, appending b to
 * a's neighbor list -- the PRIVATE LAYOUT om_region.neighbors[]/n_neighbors
 * this file's header comment already documents. */
void om_set_neighbors(om_world *w, uint32_t a, uint32_t b) {
    if (!w || a >= w->n_regions) return;
    om_region *r = &w->regions[a];
    if (r->n_neighbors >= OM_MAX_NEIGHBORS) return;
    r->neighbors[r->n_neighbors++] = b;
}

/* R-080-01: identical stats at every difficulty -- difficulty is unused by
 * design, reading E-11's own builtin roster (w = NULL, see om_unit_power's
 * comment below for why that is safe). */
int om_unit_get_profile(uint32_t unit_type, int difficulty, om_unit_profile *out) {
    (void)difficulty;
    if (!out) return 0;
    out->unit_type = unit_type;
    out->hp = om_unit_profile_max_hp(NULL, (int)unit_type);
    out->base_damage = om_unit_profile_base_damage(NULL, (int)unit_type);
    out->attack_interval = om_unit_profile_attack_interval(NULL, (int)unit_type);
    out->power = om_unit_power(unit_type);
    return 1;
}

/* R-074-06 / Q-074-01: power = HP * base_damage / attack_interval,
 * normalized so the anchor type reads OM_MISSION_POWER_ANCHOR_VALUE. Reads
 * E-11's own per-type accessors (csrc/unit.c) with w = NULL: every id below
 * OM_UNIT_TYPE_COUNT is a builtin roster entry and om_get_profile's builtin
 * branch never dereferences w, so this never needs a world. */
double om_unit_power(uint32_t unit_type) {
    double hp = om_unit_profile_max_hp(NULL, (int)unit_type);
    double dmg = om_unit_profile_base_damage(NULL, (int)unit_type);
    double interval = om_unit_profile_attack_interval(NULL, (int)unit_type);
    if (interval <= 0.0) return 0.0;
    double raw = hp * dmg / interval;

    double anchor_hp = om_unit_profile_max_hp(NULL, OM_MISSION_POWER_ANCHOR_UNIT_TYPE);
    double anchor_dmg = om_unit_profile_base_damage(NULL, OM_MISSION_POWER_ANCHOR_UNIT_TYPE);
    double anchor_interval = om_unit_profile_attack_interval(NULL, OM_MISSION_POWER_ANCHOR_UNIT_TYPE);
    if (anchor_interval <= 0.0) return 0.0;
    double anchor_raw = anchor_hp * anchor_dmg / anchor_interval;
    if (anchor_raw <= 0.0) return 0.0;

    return (raw / anchor_raw) * OM_MISSION_POWER_ANCHOR_VALUE;
}

int om_objective_set_center(om_world *w, uint32_t objective_idx, double x, double y) {
    if (!w || objective_idx >= OM_MISSION_MAX_OBJECTIVES) return 0;
    om_mission_state *st = om_mis(w);
    st->objective_center[objective_idx].x = x;
    st->objective_center[objective_idx].y = y;
    st->objective_center_set[objective_idx] = 1;
    return 1;
}
int om_objective_get_done(const om_world *w, uint32_t idx) {
    const om_mission_state *st = om_mis_ro(w);
    if (!st || idx >= st->n_objectives) return -1;
    const om_mission_objective *o = &st->objectives[idx];
    if (o->spec.is_failed) return 2;
    return (o->spec.is_complete || o->spec.completion >= 1.0) ? 1 : 0;
}
